
(()=>{
 const frames=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
 const apply=()=>{
  const head=document.querySelector('.replay-question-head span');
  if(!head||!String(head.textContent||'').trim().startsWith('LPOINTS1.176'))return;
  const stage=document.querySelector('[data-standard-video]'); if(!stage)return;
  const img=stage.querySelector('.replay-local-freeze img'); if(!img)return;
  const cls=stage.className||''; const m=cls.match(/phase-(\d)/); const phase=m?Number(m[1]):0;
  if(phase>=0&&phase<3&&img.src!==frames[phase]) img.src=frames[phase];
 };
 new MutationObserver(apply).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class','src']});
 [0,50,150,500].forEach(ms=>setTimeout(apply,ms));
})();
